const cartItems=()=>state.cart.map(c=>({...c,p:find(c.id)})).filter(x=>x.p);
function saveCart(){try{localStorage.setItem(cartKey,JSON.stringify(state.cart))}catch{};if(!state.cart.length)dismissAssist();$('#cartBtn').classList.toggle('has-items',state.cart.length>0);$('#cartCount').textContent=state.cart.reduce((n,c)=>n+c.qty,0);syncCartControls()}
function toast(t,added=false){const el=$('#toast');el.classList.toggle('is-added',added);el.innerHTML=added?ADDED_ICON:'';el.append(document.createTextNode(t));el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),added?3000:2500)}
function purchaseContent(p,mode='card'){
 const variant=activeVariant(p),options=productOptions(p),count=state.cart.find(x=>x.id===p.id&&(x.variant||'')===variant)?.qty||0,available=canBuy(p),cap=state.live?Math.min(10,stock(p)):10,label=choiceName(p,variant),suffix=label?'، '+label:'';
 const change=options.length&&mode==='card'?`<button type="button" class="variant-change" data-choose-option="${safe(p.id)}">${label?safe(label)+' · تغيير':'اختاري '+safe(optionLabel(p))}</button>`:'';
 if(!count)return `${change}<button class="${mode==='card'?'product-btn':'btn'}" data-add="${safe(p.id)}" ${!available?'disabled':''}>${available?(options.length&&!variant?'اختاري '+safe(optionLabel(p))+' +':tx('أضيفي للسلة +','Add to bag +')):tx('غير متوفر','Unavailable')}</button>`;
 return `${change}<span class="purchase-added">${ADDED_ICON}<span>${tx('تمت الإضافة إلى السلة','Added to bag')}</span></span><div class="cart-control" role="group" aria-label="كمية ${safe(pname(p)+suffix)}"><button class="cart-plus" data-add="${safe(p.id)}" aria-label="زيادة كمية ${safe(pname(p)+suffix)}" ${!available||totalQty(p.id)>=cap?'disabled':''}>+</button><output aria-live="polite">${count} ${tx('في السلة','in bag')}</output><button data-qty="${safe(p.id)}" data-variant="${safe(variant)}" data-step="-1" aria-label="تقليل كمية ${safe(pname(p)+suffix)}">−</button></div>`
}
function purchase(p,mode='card'){return `<div class="purchase-area" data-purchase="${safe(p.id)}" data-mode="${mode}">${purchaseContent(p,mode)}</div>`}
function syncCartControls(){document.querySelectorAll('[data-purchase]').forEach(area=>{const p=find(area.dataset.purchase);if(!p)return;const focused=area.contains(document.activeElement)?document.activeElement:null;const action=focused?.hasAttribute('data-add')?'[data-add]':focused?.hasAttribute('data-qty')?'[data-qty]':null;area.innerHTML=purchaseContent(p,area.dataset.mode);if(action)area.querySelector(action)?.focus({preventScroll:true})});syncWhatsAppLinks()}
function add(id,amount=1,requested){
 if(guardCartEdit())return;
 if(isBundleId(id)){addPromotion(id);return}const p=find(id);if(!p)return;
 const variant=requested??activeVariant(p);if(productOptions(p).length&&!selectedOption(p,variant)){openOptions(p);return}
 const next=state.cart.map(x=>({...x})),current=next.find(x=>x.id===id&&(x.variant||'')===variant);
 if(!current&&next.length>=20){toast(tx('يمكن إضافة 20 اختيارًا مختلفًا في الطلب الواحد','Your bag can contain up to 20 selections.'));return}
 if(!canBuy(p)){toast(tx('هذا المنتج غير متاح للطلب حاليًا','This item is currently unavailable'));return}
 if(current)current.qty+=amount;else next.push({id,qty:amount,variant});
 const error=purchaseCartError(next,state.products,state.promotions,{checkStock:state.live});if(error){toast(translateText(error));return}
 state.selectedOptions[id]=variant;state.cart=next;experienceMetrics.measure('cart_add');saveCart();refreshCartViews();if(parseRoute().path!=='/checkout'&&$('#drawer').hidden&&!document.querySelector('#lumaChat[open]'))scheduleAssist(id);toast(tx('تمت الإضافة إلى السلة','Added to bag'),true)
}
document.addEventListener('trend:luma-add',event=>{
 const id=event.detail?.id;if(typeof id!=='string'||!/^TS[A-Z0-9-]{4,64}$/.test(id))return;event.preventDefault();
 const p=find(id);if(!p){event.detail.respond?.({added:false,message:'تعذر قراءة المنتج؛ حدّثي المتجر.'});return}
 const needsOptions=productOptions(p).length>0&&!selectedOption(p,activeVariant(p));
 if(needsOptions)event.detail.respond?.({needsOptions:true});
 const before=state.cart.filter(x=>x.id===id).reduce((n,x)=>n+x.qty,0);add(id);const after=state.cart.filter(x=>x.id===id).reduce((n,x)=>n+x.qty,0);
 if(!needsOptions)event.detail.respond?.({added:after>before,message:after>before?'أضيفت لسلتكِ.':'تعذرت الإضافة؛ راجعي المخزون أو خيارات المنتج.'});
});
function qty(id,step,variant=''){
 if(guardCartEdit())return;
 const next=state.cart.map(x=>({...x})),item=next.find(x=>x.id===id&&(x.variant||'')===variant);if(!item)return;item.qty+=step;
 const cart=next.filter(x=>x.qty>0);if(cart.length){const error=purchaseCartError(cart,state.products,state.promotions,{checkStock:state.live});if(error){toast(translateText(error));return}}
 state.cart=cart;saveCart();refreshCartViews()
}
function brandDiscovery(products,query={},compact=false){const representatives=[],seen=new Set(),preferred=['arencia','cosrx','anua','skin1004','beautyofjoseon','dralthea','axisy','medicube'];for(const p of curatedProducts(products)){const key=brandKey(p.brand);if(!key||seen.has(key))continue;seen.add(key);representatives.push(p)}const rank=p=>preferred.indexOf(brandKey(p.brand))<0?99:preferred.indexOf(brandKey(p.brand)),chosen=representatives.sort((a,b)=>rank(a)-rank(b)).slice(0,8);return chosen.length?`<nav class="brand-discovery ${compact?'brand-discovery-compact':''}" aria-label="${tx('تسوّقي حسب الماركة','Shop by brand')}"><h3>${tx('ماركتكِ المفضلة، أقرب إليكِ','Your favourite brands, closer')}</h3><p>${tx('اختاري الماركة لتشاهدي منتجاتها.','Choose a brand to explore its products.')}</p><div class="brand-rail">${chosen.map(p=>`<a class="brand-tile" href="${safe(discoveryHref(query,{brand:brandName(p.brand)}))}"><img src="${safe(thumb(p))}" alt="" width="68" height="76" loading="lazy" decoding="async"/><b dir="auto">${safe(brandName(p.brand))}</b></a>`).join('')}</div></nav>`:''}
function discoveryFilters(query){const tags=[];if(query.get('brand'))tags.push(['brand',brandName(query.get('brand'))]);if(query.get('q'))tags.push(['q',query.get('q')]);const type=PRODUCT_TYPES.find(t=>t.id===query.get('type'));if(type)tags.push(['type',type.label]);return tags.length?`<nav class="discovery-active" aria-label="${tx('الفلاتر المطبقة','Applied filters')}">${tags.map(([key,label])=>`<a href="${safe(discoveryHref(query,{[key]:''}))}" aria-label="${safe(tx('إزالة الفلتر: ','Remove filter: ')+label)}">${safe(label)} <span aria-hidden="true">×</span></a>`).join('')}</nav>`:''}
function card(p){const discount=pdiscount(p),d=info(p),image=thumb(p),summary=productCardSummary(p,locale()),size=productSizeLabel(p,locale()),saving=Math.max(0,pref(p)-pprice(p));return `<article class="product-card">${favoriteButton(p)}<a class="product-art" href="#/product/${encodeURIComponent(p.id)}"><img src="${safe(image)}" alt="صورة ${safe(pname(p))}" loading="lazy" decoding="async" width="400" height="460"/>${discount?`<span class="discount-pill"><b lang="en">SALE</b> −${discount}%</span>`:''}</a><div class="product-info">${brandLink(p,'brand-line')}<a class="product-name" href="#/product/${encodeURIComponent(p.id)}" dir="auto">${safe(pname(p))}</a>${d.nameAr?`<small class="product-original" dir="auto" ${locale()==='en'?'hidden':''}>${safe(p.name)}</small>`:''}${summary?`<p class="product-tagline product-purpose">${safe(summary)}</p>`:`<span class="subcat">${safe(p.subcat||p.subcategory||p.category)}</span>`}${size?`<small class="product-size" dir="auto">${safe(size)}</small>`:''}<div class="price-row"><strong>${money(pprice(p))}</strong>${discount?`<del class="old-price" aria-label="السعر قبل الخصم">${money(pref(p))}</del>`:''}</div>${discount&&saving?`<small class="product-saving">${tx('وفّري','Save')} ${money(saving)}</small>`:''}${!canBuy(p)?'<small class="tiny-note">غير متوفر حاليًا</small>':''}${purchase(p)}${p.id==='TS0202'&&availableOffers().some(o=>o.id==='PROMONOV3-SKY-TRIO')?`<a class="product-offer-link" href="#/offers?offer=PROMONOV3-SKY-TRIO">${tx('3 حبات بـ10 دنانير ♡','3 for 10 JOD ♡')}</a>`:''}</div></article>`}
const searchDialog=createSearchDialog({panel:$('#searchPanel'),trigger:$('#searchBtn'),field:$('#globalSearch'),box:$('#globalSuggestions')});
