function openSearch(mode='browse'){if(mode==='checkout'&&guardCartEdit())return;dismissAssist();if(mode!=='checkout')closeDrawer();$('#searchTitle').textContent=mode==='checkout'?tx('أضيفي لمسة أخرى لطلبكِ','Add another favourite'):tx('لنجد ما تحبّين ♡','Find a little something you love ♡');$('#globalSearch').placeholder=tx('اكتبي اسم المنتج أو الماركة…','Search by product or brand…');$('#searchAllResults').hidden=mode==='checkout';searchDialog.open(mode);updateSearchHelp();}
