let storyRequest=0;
async function storyDetail(p){
 const request=++storyRequest;
 const expected=parseRoute().path;
 if(app.querySelector('[data-product-loading]')?.dataset.productLoading!==p.id)app.innerHTML=productLoading(p,locale());
 const profile=isKoreanCare(p)?await loadProductStory(p):null;
 if(request!==storyRequest||parseRoute().path!==expected)return;
 document.body.classList.add('is-product-story');
 const setSelection=quantity=>{if(guardCartEdit())return false;const current=find(p.id),cap=state.live?Math.min(10,stock(current||{})):10;if(!current||!canBuy(current)||!Number.isInteger(quantity)||quantity<1||quantity>cap){toast(tx('الكمية المطلوبة غير متاحة؛ راجعي السلة.','This quantity is unavailable. Please review your bag.'));return false}const variant=activeVariant(p);if(productOptions(p).length&&!selectedOption(p,variant)){toast(tx('اختاري الدرجة أو النسخة التي تحبينها أولًا.','Choose your preferred tone or version first.'));$('[data-select-option]')?.focus();return false}const other=state.cart.filter(x=>x.id!==p.id||(x.variant||'')!==variant);if(other.length>=20){toast(tx('يمكن إضافة 20 اختيارًا مختلفًا في الطلب.','Your order can contain up to 20 different selections.'));return false}const next=[...other,{id:p.id,qty:quantity,variant}];const error=purchaseCartError(next,state.products,state.promotions,{checkStock:state.live});if(error){toast(translateText(error));return false}state.cart=next;experienceMetrics.measure('cart_add');saveCart();refreshCartViews();return true};
 mountProductStory(app,{profile,options:optionFields(p),images:productGallery(p,state.galleries),bundles:productOffers(p),product:p,name:pname(p),image:largeImageFor(p,p.image||p.image_url,state.thumbnails),cap:canBuy(p)?(state.live?Math.min(10,stock(p)):10):0,live:state.live,quantity:totalQty(p.id)||1,inBag:totalQty(p.id),hasOtherItems:state.cart.some(x=>x.id!==p.id),promotions:state.promotions,taxonomy:productTaxonomy(p),brand:brandLink(p,'detail-brand'),onCheckout:quantity=>{if(setSelection(quantity))openQuickCheckout()},onAdd:quantity=>{if(!setSelection(quantity))return false;toast(tx('تمت الإضافة إلى السلة','Added to bag'),true);scheduleAssist(p.id);return true},onZoom:(images,name,index)=>{dismissAssist();imageZoom.open(images,name,index)},onShare:()=>{dismissAssist();productShare.open(p,pname(p))}});
 browseBackLink();experienceMetrics.measure('product_view');app.querySelector('.story-brand-row').insertAdjacentHTML('afterbegin',favoriteButton(p,true));syncCollectionButtons();if(!canBuy(p)){const nearby=nearbyAvailableProducts(state.products,p,{limit:2});if(nearby.length)app.querySelector('#storyPurchase').insertAdjacentHTML('afterend','<section class="stock-alternatives"><h2>'+tx('خيارات قريبة متوفرة','Similar available choices')+'</h2><p>'+tx('قارني تفاصيل كل منتج واختاري ما يناسبكِ.','Compare each product and choose what suits you.')+'</p><div class="products-grid">'+nearby.map(card).join('')+'</div></section>');}
 const help=document.createElement('div');help.innerHTML=productWhatsApp(p);app.querySelector('.story-intro').append(help);applyProductLayout();mountProductVideos($('[data-product-videos]',app),{productId:p.id});mountFeaturedVideo($('[data-featured-video]',app),{productId:p.id});
 refreshDetailRecommendations();
 const summaryElement=$('#storyReviewSummary');
 mountStoreReviews($('#productReviews'),{productId:p.id,live:state.live,onSummary:summary=>renderReviewSummary(summaryElement,summary,state.siteSettings.reviewSubmissionsEnabled)});
}

const checkoutSuggestions=createCheckoutSuggestions({document,getContext:()=>({products:state.products,cart:state.cart,promotions:state.promotions,language:locale(),name:pname,image:thumb,price:p=>money(pprice(p)),total:()=>money(cartQuote().totalFils),options:p=>productOptions(p).map(o=>({id:o.id,label:optionText(p,o)}))}),onAdd:(id,variant)=>{if(guardCartEdit())return false;const before=totalQty(id);add(id,1,variant);return totalQty(id)>before}});
const quickCheckout=document.createElement('dialog');quickCheckout.className='quick-checkout';quickCheckout.setAttribute('aria-labelledby','quickCheckoutTitle');document.body.append(quickCheckout);
let quickFocus,quickOverflow='';
function closeQuickCheckout(force=false){if(!quickCheckout.open)return;checkoutSuggestions.close({restoreFocus:false});if(orderBusy&&!force){const status=$('[data-quick-status]',quickCheckout);if(status)status.textContent=tx('ننتظر نتيجة التأكيد؛ لحظات فقط.','Waiting for confirmation. One moment, please.');return}rememberCheckout();quickCheckout.close();quickCheckout.innerHTML='';document.body.style.overflow=quickOverflow;document.body.classList.toggle('is-checkout',parseRoute().path==='/checkout');if(quickFocus?.isConnected)quickFocus.focus({preventScroll:true})}
