 f.addEventListener('input',e=>{rememberCheckout();const input=e.target;input.removeAttribute('aria-invalid');const field=f.querySelector('[data-field-error="'+input.name+'"]');if(field)field.textContent='';$('#checkoutError').textContent=''});f.addEventListener('change',rememberCheckout);
