function clearPendingCheckout(){pendingCheckout=null;savePendingCheckout(sessionStorage,null)}
function completeReceipt(receipt,method){state.cart=[];saveCart();checkoutDraft={};clearPendingCheckout();success(receipt.orderId||'—',receipt.paymentMethod||method,receipt.shippingFeeFils,receipt.totalFils)}
async function recoverCheckout(key){try{const response=await requestWithDeadline(fetch,'/api/order-status',{method:'POST',headers:{'content-type':'application/json','x-idempotency-key':key},body:'{}'},5000);const j=await response.json();return response.ok&&j.received?j:null}catch{return null}}
// A receipt lookup is read-only. Recover it before current stock or empty fields
// can block a customer returning after an interrupted confirmation.
async function resumePendingCheckout(){
 if(!pendingCheckout||!state.live)return false;
 orderBusy=true;
 try{const receipt=await recoverCheckout(pendingCheckout.key);if(!receipt)return false;completeReceipt(receipt);return true}
 finally{orderBusy=false;refreshCheckoutSummary()}
}
async function submitOrder(e){
 e.preventDefault();const f=e.currentTarget,btn=$('#confirmButton'),error=$('#checkoutError');if(btn.disabled||orderBusy)return;orderBusy=true;refreshCheckoutSummary();btn.disabled=true;btn.textContent=tx('جاري التحقق…','Checking your details…');try{rememberCheckout();showFieldErrors({});error.textContent='';
 if(state.live&&pendingCheckout){const receipt=await recoverCheckout(pendingCheckout.key);if(receipt){completeReceipt(receipt);return}}
 const selectionError=purchaseCartError(state.cart,state.products,state.promotions,{checkStock:state.live});if(selectionError){error.textContent=translateText(selectionError);error.focus();return}
 const data={...Object.fromEntries(new FormData(f).entries()),locale:locale()};let result;
 try{result=validateCheckout(data,(await requestWithDeadline(()=>loadContactPhone(),'phone-validation',{},8000)).normalizeContactPhone)}catch{error.textContent=tx('تعذّر تحميل التحقق من الهاتف؛ تحققي من الاتصال وحاولي مجددًا.','Phone validation could not load. Check your connection and try again.');return}
 if(!result.valid){showFieldErrors(result.fields);error.textContent=tx('راجعي الحقول المعلّمة أدناه؛ باقي بياناتكِ محفوظة.','Check the highlighted fields. Your other details are preserved.');return}
 btn.disabled=true;btn.textContent=tx('جاري تسجيل الطلب…','Placing your order…');
 try{
  const experienceSession=experienceMetrics.getSession();const q=cartQuote(),payload=JSON.stringify({...result.values,...(experienceSession?{experienceSession,experienceDevice:window.innerWidth<768?'mobile':'desktop'}:{}),expectedSubtotalFils:q.subtotalFils,expectedTotalFils:q.totalFils,items:state.cart.map(x=>({id:x.id,qty:x.qty,...(x.variant?{variant:x.variant}:{}),...(isBundleId(x.id)?{options:x.options||{}}:{})}))});
  if(!pendingCheckout)pendingCheckout={key:newCheckoutKey(),at:Date.now()};savePendingCheckout(sessionStorage,pendingCheckout);
  const response=await requestWithDeadline(fetch,'/api/orders',{method:'POST',headers:{'content-type':'application/json','x-idempotency-key':pendingCheckout.key},body:payload});const j=await response.json().catch(()=>({}));
  if(response.ok&&j.orderId){completeReceipt(j,data.payment);return}
  if(response.status>=400&&response.status<500){clearPendingCheckout();if(j.fields){showFieldErrors(j.fields);error.textContent=tx('راجعي الحقول المعلّمة، ثم أكّدي الطلب من جديد.','Check the highlighted fields, then confirm again.');return}
   if(response.status===409){try{const r=await requestWithDeadline(fetch,'/api/catalog',{},7000);if(r.ok){const c=await r.json();state.products=curatedProducts(storefrontProducts(c.products));state.promotions=c.promotions||[];refreshCheckoutSummary()}}catch{}error.textContent=tx('تغيّر سعر أو توفر أحد المنتجات. راجعي الملخص والسلة قبل تأكيد الطلب مجددًا؛ بياناتكِ محفوظة.','An item’s price or availability changed. Review your bag and summary before confirming again. Your details are preserved.');return}
   error.textContent=response.status===429?tx('محاولات كثيرة خلال وقت قصير. انتظري قليلًا ثم حاولي مجددًا.','Too many attempts. Please wait a little and try again.'):tx(j.error||'تعذّر تسجيل الطلب الآن. حاولي مجددًا.','We could not place the order. Check your bag and try again.');return;
  }
  throw Error('UNCERTAIN_REQUEST');
 }catch{
  const receipt=pendingCheckout?await recoverCheckout(pendingCheckout.key):null;if(receipt){completeReceipt(receipt,data.payment);return}
  error.textContent=tx('لم يصلنا تأكيد نهائي بسبب الاتصال. بياناتكِ وسلتكِ محفوظة هنا. اضغطي تأكيد طلبي الآن لإعادة التحقق والمحاولة بأمان، أو استخدمي المساعدة عبر واتساب أسفل الصفحة.','The connection did not return a final confirmation. Your details and bag are preserved here. Press Confirm my order to safely check and retry, or use WhatsApp help below.');
 }finally{if(btn.isConnected)btn.disabled=false}
 }finally{orderBusy=false;refreshCheckoutSummary();const current=$('#confirmButton');if(current){current.disabled=!state.cart.length;current.textContent=tx('تأكيد طلبي الآن','Confirm my order')}}
}

